import java.math.BigDecimal;
import java.math.RoundingMode;

/**
 * 配送费与服务费计算工具类。
 *
 * 规则来源：docs/费用规则.md
 * - 配送费：itemCount=0 返回 0；amount>200 且 itemCount>0 返回 0；否则返回 12。
 * - 服务费：amount=0 返回 0；0<amount<=100 返回 2；amount>100 返回 5。
 * - 金额单位：元；返回值统一保留 2 位小数。
 * - 非法输入：null、负金额、负件数，抛 IllegalArgumentException。
 */
public final class FeeCalculator {

    private static final BigDecimal DELIVERY_FEE_FREE_THRESHOLD = new BigDecimal("200");
    private static final BigDecimal DELIVERY_FEE_NORMAL = new BigDecimal("12");

    private static final BigDecimal SERVICE_FEE_ZERO = BigDecimal.ZERO;
    private static final BigDecimal SERVICE_FEE_LOW = new BigDecimal("2");
    private static final BigDecimal SERVICE_FEE_HIGH = new BigDecimal("5");
    private static final BigDecimal SERVICE_FEE_LOW_UPPER_BOUND = new BigDecimal("100");

    private FeeCalculator() {
        // 工具类，禁止实例化
    }

    /**
     * 计算配送费。
     *
     * @param amount    订单金额，单位元，不能为 null 且必须 >= 0
     * @param itemCount 商品件数，不能小于 0
     * @return 配送费，保留 2 位小数
     * @throws IllegalArgumentException 当 amount 为 null、amount < 0 或 itemCount < 0
     */
    public static BigDecimal deliveryFee(BigDecimal amount, int itemCount) {
        validateAmount(amount);
        validateItemCount(itemCount);

        if (itemCount == 0) {
            return scale2(BigDecimal.ZERO);
        }

        if (amount.compareTo(DELIVERY_FEE_FREE_THRESHOLD) > 0) {
            return scale2(BigDecimal.ZERO);
        }

        return scale2(DELIVERY_FEE_NORMAL);
    }

    /**
     * 计算服务费。
     *
     * @param amount 订单金额，单位元，不能为 null 且必须 >= 0
     * @return 服务费，保留 2 位小数
     * @throws IllegalArgumentException 当 amount 为 null 或 amount < 0
     */
    public static BigDecimal serviceFee(BigDecimal amount) {
        validateAmount(amount);

        if (amount.compareTo(BigDecimal.ZERO) == 0) {
            return scale2(SERVICE_FEE_ZERO);
        }

        if (amount.compareTo(SERVICE_FEE_LOW_UPPER_BOUND) <= 0) {
            return scale2(SERVICE_FEE_LOW);
        }

        return scale2(SERVICE_FEE_HIGH);
    }

    private static void validateAmount(BigDecimal amount) {
        if (amount == null) {
            throw new IllegalArgumentException("amount must not be null");
        }
        if (amount.compareTo(BigDecimal.ZERO) < 0) {
            throw new IllegalArgumentException("amount must be greater than or equal to 0");
        }
    }

    private static void validateItemCount(int itemCount) {
        if (itemCount < 0) {
            throw new IllegalArgumentException("itemCount must be greater than or equal to 0");
        }
    }

    private static BigDecimal scale2(BigDecimal value) {
        return value.setScale(2, RoundingMode.HALF_UP);
    }
}
