import java.math.BigDecimal;
import java.math.RoundingMode;

/**
 * 纯 Java 费用计算工具类。
 * 仅包含配送费和服务费两个计算方法，不涉及外部服务。
 */
public final class FeeCalculator {

    private FeeCalculator() {
        // 工具类禁止实例化
    }

    /**
     * 计算配送费。
     *
     * @param amount    订单金额（元），不能为 null，且必须大于等于 0
     * @param itemCount 件数，不能小于 0
     * @return 配送费，保留 2 位小数
     * @throws IllegalArgumentException 如果金额为 null、金额小于 0 或件数小于 0
     */
    public static BigDecimal deliveryFee(BigDecimal amount, int itemCount) {
        validateAmount(amount);
        if (itemCount < 0) {
            throw new IllegalArgumentException("itemCount must be >= 0");
        }

        if (itemCount == 0) {
            return BigDecimal.ZERO.setScale(2, RoundingMode.UNNECESSARY);
        }

        if (amount.compareTo(new BigDecimal("200")) > 0) {
            return BigDecimal.ZERO.setScale(2, RoundingMode.UNNECESSARY);
        }

        return new BigDecimal("12").setScale(2, RoundingMode.UNNECESSARY);
    }

    /**
     * 计算服务费。
     *
     * @param amount 订单金额（元），不能为 null，且必须大于等于 0
     * @return 服务费，保留 2 位小数
     * @throws IllegalArgumentException 如果金额为 null 或金额小于 0
     */
    public static BigDecimal serviceFee(BigDecimal amount) {
        validateAmount(amount);

        if (amount.compareTo(BigDecimal.ZERO) == 0) {
            return BigDecimal.ZERO.setScale(2, RoundingMode.UNNECESSARY);
        }

        if (amount.compareTo(new BigDecimal("100")) <= 0) {
            return new BigDecimal("2").setScale(2, RoundingMode.UNNECESSARY);
        }

        return new BigDecimal("5").setScale(2, RoundingMode.UNNECESSARY);
    }

    private static void validateAmount(BigDecimal amount) {
        if (amount == null) {
            throw new IllegalArgumentException("amount must not be null");
        }
        if (amount.compareTo(BigDecimal.ZERO) < 0) {
            throw new IllegalArgumentException("amount must be >= 0");
        }
    }
}
