import java.math.BigDecimal;

/**
 * FeeCalculator 的独立测试类。
 * 使用 main 方法加断言，不依赖测试框架。
 */
public class FeeCalculatorTest {

    public static void main(String[] args) {
        testDeliveryFee();
        testServiceFee();
        testInputImmutability();
        System.out.println("All tests passed.");
    }

    private static void testDeliveryFee() {
        // 件数为 0，金额任意合法值，配送费为 0
        assertEquals(new BigDecimal("0.00"), FeeCalculator.deliveryFee(new BigDecimal("0"), 0));
        assertEquals(new BigDecimal("0.00"), FeeCalculator.deliveryFee(new BigDecimal("100"), 0));
        assertEquals(new BigDecimal("0.00"), FeeCalculator.deliveryFee(new BigDecimal("200"), 0));
        assertEquals(new BigDecimal("0.00"), FeeCalculator.deliveryFee(new BigDecimal("200.01"), 0));

        // 件数大于 0，金额严格大于 200，配送费为 0
        assertEquals(new BigDecimal("0.00"), FeeCalculator.deliveryFee(new BigDecimal("200.01"), 1));
        assertEquals(new BigDecimal("0.00"), FeeCalculator.deliveryFee(new BigDecimal("300"), 1));

        // 件数大于 0，金额恰好 200，配送费为 12
        assertEquals(new BigDecimal("12.00"), FeeCalculator.deliveryFee(new BigDecimal("200"), 1));

        // 件数大于 0，金额小于 200，配送费为 12
        assertEquals(new BigDecimal("12.00"), FeeCalculator.deliveryFee(new BigDecimal("0"), 1));
        assertEquals(new BigDecimal("12.00"), FeeCalculator.deliveryFee(new BigDecimal("100"), 1));
        assertEquals(new BigDecimal("12.00"), FeeCalculator.deliveryFee(new BigDecimal("199.99"), 1));

        // 非法输入：null 金额
        assertThrowsIllegalArgument(() -> FeeCalculator.deliveryFee(null, 1));
        // 非法输入：负金额
        assertThrowsIllegalArgument(() -> FeeCalculator.deliveryFee(new BigDecimal("-0.01"), 1));
        // 非法输入：负件数
        assertThrowsIllegalArgument(() -> FeeCalculator.deliveryFee(new BigDecimal("100"), -1));
    }

    private static void testServiceFee() {
        // 金额为 0，服务费为 0
        assertEquals(new BigDecimal("0.00"), FeeCalculator.serviceFee(new BigDecimal("0")));
        assertEquals(new BigDecimal("0.00"), FeeCalculator.serviceFee(new BigDecimal("0.00")));

        // 0 < amount <= 100，服务费为 2
        assertEquals(new BigDecimal("2.00"), FeeCalculator.serviceFee(new BigDecimal("0.01")));
        assertEquals(new BigDecimal("2.00"), FeeCalculator.serviceFee(new BigDecimal("100")));
        assertEquals(new BigDecimal("2.00"), FeeCalculator.serviceFee(new BigDecimal("100.00")));

        // amount > 100，服务费为 5
        assertEquals(new BigDecimal("5.00"), FeeCalculator.serviceFee(new BigDecimal("100.01")));
        assertEquals(new BigDecimal("5.00"), FeeCalculator.serviceFee(new BigDecimal("200")));

        // 非法输入：null 金额
        assertThrowsIllegalArgument(() -> FeeCalculator.serviceFee(null));
        // 非法输入：负金额
        assertThrowsIllegalArgument(() -> FeeCalculator.serviceFee(new BigDecimal("-0.01")));
    }

    private static void testInputImmutability() {
        BigDecimal amount = new BigDecimal("123.456");
        BigDecimal original = amount;
        FeeCalculator.deliveryFee(amount, 1);
        FeeCalculator.serviceFee(amount);
        assertEquals(original, amount);
    }

    private static void assertEquals(BigDecimal expected, BigDecimal actual) {
        if (expected.compareTo(actual) != 0) {
            throw new AssertionError("Expected " + expected + " but got " + actual);
        }
    }

    private static void assertThrowsIllegalArgument(Runnable runnable) {
        try {
            runnable.run();
            throw new AssertionError("Expected IllegalArgumentException but no exception was thrown");
        } catch (IllegalArgumentException e) {
            // expected
        }
    }
}
