 */
public class FeeCalculatorTest {

    private static int passed = 0;
    private static int failed = 0;

    public static void main(String[] args) {
        // ===== 配送费：正常与边界 =====
        // itemCount == 0 返回 0（无论金额）
        assertDelivery("配送费 itemCount=0, amount=0", "0.00", BigDecimal.ZERO, 0);
        assertDelivery("配送费 itemCount=0, amount=200", "0.00", new BigDecimal("200"), 0);
        assertDelivery("配送费 itemCount=0, amount=999", "0.00", new BigDecimal("999"), 0);

        // itemCount > 0 且 amount 严格大于 200 免配送费
        assertDelivery("配送费 amount=200.01, itemCount=1", "0.00", new BigDecimal("200.01"), 1);
        assertDelivery("配送费 amount=201, itemCount=1", "0.00", new BigDecimal("201"), 1);
        assertDelivery("配送费 amount=1000, itemCount=5", "0.00", new BigDecimal("1000"), 5);

        // amount 恰好等于 200 不免配送，返回 12
        assertDelivery("配送费 amount=200, itemCount=1", "12.00", new BigDecimal("200"), 1);

        // 阈值下相邻金额
        assertDelivery("配送费 amount=199.99, itemCount=1", "12.00", new BigDecimal("199.99"), 1);

        // 其余合法情况返回 12
        assertDelivery("配送费 amount=0, itemCount=1", "12.00", BigDecimal.ZERO, 1);
        assertDelivery("配送费 amount=100, itemCount=1", "12.00", new BigDecimal("100"), 1);
        assertDelivery("配送费 amount=50.5, itemCount=3", "12.00", new BigDecimal("50.5"), 3);

        // ===== 服务费：正常与边界 =====
        // amount == 0 返回 0
        assertService("服务费 amount=0", "0.00", BigDecimal.ZERO);

        // 0 < amount <= 100 返回 2
        assertService("服务费 amount=0.01", "2.00", new BigDecimal("0.01"));
        assertService("服务费 amount=50", "2.00", new BigDecimal("50"));
        assertService("服务费 amount=100", "2.00", new BigDecimal("100"));

        // amount 严格大于 100 返回 5
        assertService("服务费 amount=100.01", "5.00", new BigDecimal("100.01"));
        assertService("服务费 amount=101", "5.00", new BigDecimal("101"));
        assertService("服务费 amount=200", "5.00", new BigDecimal("200"));
        assertService("服务费 amount=1000", "5.00", new BigDecimal("1000"));

        // 服务费不使用配送费的 200 阈值：amount=200 时服务费为 5，而非 0
        assertService("服务费 amount=200 不使用 200 阈值", "5.00", new BigDecimal("200"));

        // ===== 非法输入：null =====
        assertThrows("配送费 amount=null", () -> FeeCalculator.deliveryFee(null, 1));
        assertThrows("服务费 amount=null", () -> FeeCalculator.serviceFee(null));

        // ===== 非法输入：负金额 =====
        assertThrows("配送费 amount=-0.01", () -> FeeCalculator.deliveryFee(new BigDecimal("-0.01"), 1));
        assertThrows("配送费 amount=-100", () -> FeeCalculator.deliveryFee(new BigDecimal("-100"), 1));
        assertThrows("服务费 amount=-0.01", () -> FeeCalculator.serviceFee(new BigDecimal("-0.01")));
        assertThrows("服务费 amount=-100", () -> FeeCalculator.serviceFee(new BigDecimal("-100")));

        // ===== 非法输入：负件数 =====
        assertThrows("配送费 itemCount=-1", () -> FeeCalculator.deliveryFee(new BigDecimal("100"), -1));
        assertThrows("配送费 itemCount=-5", () -> FeeCalculator.deliveryFee(BigDecimal.ZERO, -5));

        // ===== 输入 BigDecimal 未被修改 =====
        BigDecimal original = new BigDecimal("200.00");
        BigDecimal before = new BigDecimal(original.toString());
        FeeCalculator.deliveryFee(original, 1);
        FeeCalculator.serviceFee(original);
        if (original.compareTo(before) == 0) {
            pass("输入 BigDecimal 未被修改");
        } else {
            fail("输入 BigDecimal 被修改: 期望 " + before + "，实际 " + original);
        }

        // ===== 返回值精度为 2 位小数 =====
        BigDecimal dFee = FeeCalculator.deliveryFee(new BigDecimal("100"), 1);
        if (dFee.scale() == 2) {
            pass("配送费返回值精度为 2 位小数");
        } else {
            fail("配送费返回值精度错误: " + dFee.scale());
        }
        BigDecimal sFee = FeeCalculator.serviceFee(new BigDecimal("50"));
        if (sFee.scale() == 2) {
            pass("服务费返回值精度为 2 位小数");
        } else {
            fail("服务费返回值精度错误: " + sFee.scale());
        }

        // ===== 汇总 =====
        System.out.println("========================================");
        System.out.println("通过: " + passed + "，失败: " + failed);
        if (failed > 0) {
            System.out.println("测试结果: 失败");
            System.exit(1);
        } else {
            System.out.println("测试结果: 全部通过");
        }
    }

    // ---------- 断言辅助方法 ----------

    private static void assertDelivery(String name, String expected, BigDecimal amount, int itemCount) {
        try {
            BigDecimal actual = FeeCalculator.deliveryFee(amount, itemCount);
            BigDecimal exp = new BigDecimal(expected);
            if (actual.compareTo(exp) == 0 && actual.scale() == 2) {
                pass(name + " => " + actual);
            } else {
                fail(name + " 期望 " + exp + "(scale=2)，实际 " + actual + "(scale=" + actual.scale() + ")");
            }
        } catch (Exception e) {
            fail(name + " 抛出异常: " + e);
        }
    }

    private static void assertService(String name, String expected, BigDecimal amount) {
        try {
            BigDecimal actual = FeeCalculator.serviceFee(amount);
            BigDecimal exp = new BigDecimal(expected);
            if (actual.compareTo(exp) == 0 && actual.scale() == 2) {
                pass(name + " => " + actual);
            } else {
                fail(name + " 期望 " + exp + "(scale=2)，实际 " + actual + "(scale=" + actual.scale() + ")");
            }
        } catch (Exception e) {
            fail(name + " 抛出异常: " + e);
        }
    }

    private static void assertThrows(String name, Runnable action) {
        try {
            action.run();
            fail(name + " 期望抛出 IllegalArgumentException，但未抛出");
        } catch (IllegalArgumentException e) {
            pass(name + " 正确抛出 IllegalArgumentException: " + e.getMessage());
        } catch (Exception e) {
            fail(name + " 期望 IllegalArgumentException，实际抛出 " + e.getClass().getName());
        }
    }

    private static void pass(String msg) {
        passed++;
        System.out.println("[PASS] " + msg);
    }

    private static void fail(String msg) {
        failed++;
        System.out.println("[FAIL] " + msg);
    }
}
