import java.math.BigDecimal;
import java.math.RoundingMode;

/**
 * 费用计算工具类（纯 Java，无外部依赖）。
 *
 * 业务规则：
 * - 配送费：itemCount == 0 返回 0；itemCount > 0 且 amount > 200 返回 0；其余合法情况返回 12。
 * - 服务费：amount == 0 返回 0；0 < amount <= 100 返回 2；amount > 100 返回 5。
 *
 * 输入约束：
 * - amount 不能为 null 且必须 >= 0。
 * - itemCount 不能 < 0。
 * - 越界抛 IllegalArgumentException。
 *
 * 返回值统一保留 2 位小数，不修改输入 BigDecimal。
 */
public final class FeeCalculator {

    /** 配送费固定金额（元）。 */
    private static final BigDecimal DELIVERY_FEE = new BigDecimal("12");

    /** 配送费免收阈值（元），严格大于该值才免收。 */
    private static final BigDecimal DELIVERY_FREE_THRESHOLD = new BigDecimal("200");

    /** 服务费低档金额（元）。 */
    private static final BigDecimal SERVICE_FEE_LOW = new BigDecimal("2");

    /** 服务费高档金额（元）。 */
    private static final BigDecimal SERVICE_FEE_HIGH = new BigDecimal("5");

    /** 服务费分档阈值（元），严格大于该值进入高档。 */
    private static final BigDecimal SERVICE_FEE_THRESHOLD = new BigDecimal("100");

    /** 返回金额统一保留的小数位数。 */
    private static final int SCALE = 2;

    private FeeCalculator() {
        // 工具类，禁止实例化
    }

    /**
     * 计算配送费。
     *
     * @param amount    订单金额（元），不能为 null 且 >= 0
     * @param itemCount 件数，不能 < 0
     * @return 配送费（元），保留 2 位小数
     * @throws IllegalArgumentException 当 amount 为 null、amount < 0 或 itemCount < 0
     */
    public static BigDecimal deliveryFee(BigDecimal amount, int itemCount) {
        // 配送费业务对象独立校验：金额非空且非负
        if (amount == null) {
            throw new IllegalArgumentException("订单金额不能为 null");
        }
        if (amount.compareTo(BigDecimal.ZERO) < 0) {
            throw new IllegalArgumentException("订单金额不能小于 0，实际为：" + amount);
        }
        // 配送费业务对象独立校验：件数非负
        if (itemCount < 0) {
            throw new IllegalArgumentException("件数不能小于 0，实际为：" + itemCount);
        }

        // itemCount == 0 时配送费为 0
        if (itemCount == 0) {
            return BigDecimal.ZERO.setScale(SCALE, RoundingMode.HALF_UP);
        }

        // itemCount > 0 且 amount 严格大于 200 时免配送费
        if (amount.compareTo(DELIVERY_FREE_THRESHOLD) > 0) {
            return BigDecimal.ZERO.setScale(SCALE, RoundingMode.HALF_UP);
        }

        // 其余合法情况（含 amount == 200）配送费为 12
        return DELIVERY_FEE.setScale(SCALE, RoundingMode.HALF_UP);
    }

    /**
     * 计算服务费。
     *
     * @param amount 订单金额（元），不能为 null 且 >= 0
     * @return 服务费（元），保留 2 位小数
     * @throws IllegalArgumentException 当 amount 为 null 或 amount < 0
     */
    public static BigDecimal serviceFee(BigDecimal amount) {
        // 服务费业务对象独立校验：金额非空且非负
        if (amount == null) {
            throw new IllegalArgumentException("订单金额不能为 null");
        }
        if (amount.compareTo(BigDecimal.ZERO) < 0) {
            throw new IllegalArgumentException("订单金额不能小于 0，实际为：" + amount);
        }

        // amount == 0 时服务费为 0
        if (amount.compareTo(BigDecimal.ZERO) == 0) {
            return BigDecimal.ZERO.setScale(SCALE, RoundingMode.HALF_UP);
        }

        // 0 < amount <= 100 时服务费为 2
        if (amount.compareTo(SERVICE_FEE_THRESHOLD) <= 0) {
            return SERVICE_FEE_LOW.setScale(SCALE, RoundingMode.HALF_UP);
        }

        // amount 严格大于 100 时服务费为 5
        return SERVICE_FEE_HIGH.setScale(SCALE, RoundingMode.HALF_UP);
    }
}
