        if (amount.compareTo(BigDecimal.ZERO) < 0) {
            throw new IllegalArgumentException("金额不能小于 0");
        }
    }

    private static void validateItemCount(int itemCount) {
        if (itemCount < 0) {
            throw new IllegalArgumentException("件数不能小于 0");
        }
    }
